import { useState } from 'react'
import * as ImagePicker from 'expo-image-picker'
import { uploadImageToUploadcare } from '../uploadcare'

export interface PickedImage {
	uri: string
	uploadcareUrl?: string
	uploadcareUuid?: string
	filename?: string
	size?: number
	mimeType?: string
}

export function useImagePicker() {
	const [isUploading, setIsUploading] = useState(false)

	const pickImage = async (): Promise<PickedImage | null> => {
		try {
			const { status } = await ImagePicker.requestMediaLibraryPermissionsAsync()

			if (status !== 'granted') {
				throw new Error('Media library permissions are required')
			}

			const result = await ImagePicker.launchImageLibraryAsync({
				mediaTypes: ['images'],
				allowsEditing: true,
				quality: 1,
				allowsMultipleSelection: false
			})

			if (result.canceled) {
				return null
			}

			const asset = result.assets[0]
			return {
				uri: asset.uri,
				filename: asset.fileName || undefined,
				size: asset.fileSize,
				mimeType: asset.mimeType || undefined
			}
		} catch (error) {
			console.error('Error picking image:', error)
			throw error
		}
	}

	const pickAndUploadImage = async (): Promise<PickedImage | null> => {
		try {
			setIsUploading(true)
			const image = await pickImage()

			if (!image) {
				return null
			}

			const uploadResult = await uploadImageToUploadcare(
				image.uri,
				image.filename
			)

			return {
				...image,
				uploadcareUrl: uploadResult.cdnUrl,
				uploadcareUuid: uploadResult.uuid,
				filename: uploadResult.originalFilename,
				size: uploadResult.size,
				mimeType: uploadResult.mimeType
			}
		} catch (error) {
			console.error('Error picking and uploading image:', error)
			throw error
		} finally {
			setIsUploading(false)
		}
	}

	const takePhoto = async (): Promise<PickedImage | null> => {
		try {
			const { status } = await ImagePicker.requestCameraPermissionsAsync()

			if (status !== 'granted') {
				throw new Error('Camera permissions are required')
			}

			const result = await ImagePicker.launchCameraAsync({
				allowsEditing: true,
				quality: 1
			})

			if (result.canceled) {
				return null
			}

			const asset = result.assets[0]
			return {
				uri: asset.uri,
				filename: asset.fileName || undefined,
				size: asset.fileSize,
				mimeType: asset.mimeType || undefined
			}
		} catch (error) {
			console.error('Error taking photo:', error)
			throw error
		}
	}

	const takePhotoAndUpload = async (): Promise<PickedImage | null> => {
		try {
			setIsUploading(true)
			const image = await takePhoto()

			if (!image) {
				return null
			}

			const uploadResult = await uploadImageToUploadcare(
				image.uri,
				image.filename
			)

			return {
				...image,
				uploadcareUrl: uploadResult.cdnUrl,
				uploadcareUuid: uploadResult.uuid,
				filename: uploadResult.originalFilename,
				size: uploadResult.size,
				mimeType: uploadResult.mimeType
			}
		} catch (error) {
			console.error('Error taking photo and uploading:', error)
			throw error
		} finally {
			setIsUploading(false)
		}
	}

	return {
		pickImage,
		pickAndUploadImage,
		takePhoto,
		takePhotoAndUpload,
		isUploading
	}
}
